def solve():
    grid = []
    for _ in range(10):
        row = list(map(int, input().split()))
        grid.append(row)

    ladder = {}

    for ri in range(10):
        row_from_bottom = 10 - ri
        path_row = row_from_bottom - 1
        for ci in range(10):
            h = grid[ri][ci]
            if h == 0:
                continue
            if path_row % 2 == 0:
                pos = path_row * 10 + ci
            else:
                pos = path_row * 10 + (9 - ci)
            dest_row_from_bottom = row_from_bottom + h
            dest_path_row = dest_row_from_bottom - 1
            dest_ri = 10 - dest_row_from_bottom
            if dest_path_row % 2 == 0:
                dest_pos = dest_path_row * 10 + ci
            else:
                dest_pos = dest_path_row * 10 + (9 - ci)
            ladder[pos] = dest_pos

    E = [0.0] * 100
    for i in range(98, -1, -1):
        s = 0.0
        count_stay = 0
        for r in range(1, 7):
            nxt = i + r
            if nxt > 99:
                count_stay += 1
            else:
                best = E[nxt]
                if nxt in ladder:
                    best = min(best, E[ladder[nxt]])
                s += best
        E[i] = (1 + s / 6.0) / (1 - count_stay / 6.0)

    print(f"{E[0]:.10f}")

solve()

